{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Bumetanide, a loop diuretic sharing the sulfamoyl-anthranilic acid core, had an absolute oral bioavailability of 0.78 in normal subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tolfenamic acid, an anthranilic acid analogue, showed absolute oral bioavailability of 60.4% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Hydrochlorothiazide, a sulfonamide diuretic, had an absolute oral bioavailability of 60.2% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Azosemide, a close loop-diuretic analogue, was estimated to have only 10% bioavailability based on urinary excretion, providing contradictory low-F evidence for this chemotype.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is furosemide. Multiple close analogues with the same sulfamoyl-anthranilic acid/diuretic scaffold (bumetanide, tolfenamic acid, hydrochlorothiazide) show absolute oral bioavailability of 60-80%, well above the 20% threshold. The low-F azosemide record is less transferable because it replaces the carboxylic acid with a tetrazole and the furan with thiophene, and it does not outweigh the consistent high-F pattern. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for furosemide parent is present; the closest record is for its acyl glucuronide metabolite, which is not direct evidence for the parent.",
    "No cystic fibrosis-specific bioavailability data are supplied; disease-related changes in absorption or first-pass metabolism are not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

